3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Assigns the owner's {@code customerCode} before {@link SaveOwner} runs, formatted
12	 * {@code <REGION>-<HASH8>}: the region code derived from the postcode, then the first
13	 * eight upper-case hex characters of SHA-256 over the normalized telephone followed by
14	 * the last name. No sequence numbers are used, so the code depends only on the owner.
15	 */
16	public class AssignCustomerCode {
17	
18	    public void service(@Val Owner owner) {
19	        owner.setCustomerCode(Locality.region(owner) + "-" + hash8(blank(owner.getTelephone()) + blank(owner.getLastName())));
20	    }
21	
22	    private static String hash8(String input) {
23	        try {
24	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(input.getBytes(StandardCharsets.UTF_8));
25	            StringBuilder sb = new StringBuilder(16);
26	            for (int i = 0; i < 4; i++) {
27	                sb.append(String.format("%02X", digest[i]));
28	            }
29	            return sb.toString();
30	        }
31	        catch (NoSuchAlgorithmException ex) {
32	            throw new IllegalStateException(ex);
33	        }
34	    }
35	
36	    private static String blank(String value) {
37	        return value == null ? "" : value;
38	    }
39	}
