5	/**
6	 * Computes the single Luhn check digit (0-9) over the digits contained in an owner's
7	 * {@code customerCode}. The rightmost digit is doubled, alternating leftwards; each
8	 * doubled value above nine has nine subtracted, and the digit that makes the running
9	 * sum a multiple of ten is returned.
10	 */
11	public class CheckDigit {
12	
13	    public static Integer checkDigit(Owner owner) {
14	        String code = owner.getCustomerCode();
15	        if (code == null) {
16	            return null;
17	        }
18	        int sum = 0;
19	        boolean dbl = true;
20	        for (int i = code.length() - 1; i >= 0; i--) {
21	            char c = code.charAt(i);
22	            if (c < '0' || c > '9') {
23	                continue;
24	            }
25	            int d = c - '0';
26	            if (dbl) {
27	                d *= 2;
28	                if (d > 9) {
29	                    d -= 9;
30	                }
31	            }
32	            sum += d;
33	            dbl = !dbl;
34	        }
35	        return (10 - (sum % 10)) % 10;
36	    }
37	}
