3	import java.time.LocalDate;
4	
5	/**
6	 * Fiscal-year arithmetic for date-derived owner values. The fiscal year starts on
7	 * 1 July and is named for the calendar year it ends in, so 1 July 2025 begins the
8	 * fiscal year 'FY26'.
9	 */
10	public final class FiscalYear {
11	
12	    private FiscalYear() {
13	    }
14	
15	    /** Calendar year the fiscal year containing {@code date} ends in (July onwards rolls forward). */
16	    public static int endYear(LocalDate date) {
17	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
18	    }
19	
20	    /** 'FY&lt;YY&gt;' label for {@code date}, e.g. FY26. */
21	    public static String label(LocalDate date) {
22	        return String.format("FY%02d", endYear(date) % 100);
23	    }
24	
25	    /** Whole fiscal years elapsed from {@code from} to {@code to}. */
26	    public static int elapsed(LocalDate from, LocalDate to) {
27	        return endYear(to) - endYear(from);
28	    }
29	}
