8	/**
9	 * Derives an owner's membership standing as points, then a level. Points accrue from an
10	 * email (+2), a zero namesake count (+1), a household of three or more (+2) and tenure of
11	 * more than one elapsed fiscal year since registration (+3). The points map to a level: 1 (0-1), 2 (2-3),
12	 * 3 (4-5), 4 (6 or more).
13	 */
14	public final class MembershipLevel {
15	
16	    private MembershipLevel() {
17	    }
18	
19	    /** Membership points for the owner (see class doc). */
20	    public static int points(Owner owner, OwnerRepository ownerRepository) {
21	        int points = 0;
22	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
23	            points += 2;
24	        }
25	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
26	            points += 1;
27	        }
28	        if (HouseholdTier.isGold(owner, ownerRepository)) {
29	            points += 2;
30	        }
31	        if (tenureFiscalYears(owner) > 1) {
32	            points += 3;
33	        }
34	        return points;
35	    }
36	
37	    /** Membership level for a points total: 1 (0-1), 2 (2-3), 3 (4-5), 4 (6 or more). */
38	    public static int level(int points) {
39	        if (points >= 6) {
40	            return 4;
41	        }
42	        if (points >= 4) {
43	            return 3;
44	        }
45	        if (points >= 2) {
46	            return 2;
47	        }
48	        return 1;
49	    }
50	
51	    private static int tenureFiscalYears(Owner owner) {
52	        LocalDate registrationDate = owner.getRegistrationDate();
53	        return registrationDate == null ? 0 : FiscalYear.elapsed(registrationDate, LocalDate.now());
54	    }
55	}
