27	        long seq = SEQ.incrementAndGet();
28	        int membershipLevel = ownerMapper.toOwnerDto(owner).getMembershipLevel();
29	        AUDIT.info("{\"seq\":{},\"ownerId\":{},\"customerCode\":\"{}\",\"membershipLevel\":{},\"event\":\"OWNER_CREATED\"}",
30	            seq, owner.getId(), identifier(owner), membershipLevel);
31	    }
32	
33	    /** The owner's current primary identifier; unify into the memberId here when it lands. */
34	    private static String identifier(Owner owner) {
