5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * De-duplicates the {@code customerCode} assigned by {@link AssignCustomerCode}: when it
12	 * already belongs to another owner, append {@code -<n>} with the smallest n of 2 or more
13	 * that makes it unique, before {@link SaveOwner} runs.
14	 */
15	public class DeduplicateCustomerCode {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
18	        Set<String> taken = new HashSet<>();
19	        for (Owner other : ownerRepository.findAll()) {
20	            taken.add(other.getCustomerCode());
21	        }
22	        String base = owner.getCustomerCode();
23	        String code = base;
24	        for (int n = 2; taken.contains(code); n++) {
25	            code = base + "-" + n;
26	        }
27	        owner.setCustomerCode(code);
28	    }
29	}
